(()=>{const carousel=document.querySelector('.reel-carousel');if(!carousel)return;const track=carousel.querySelector('.reel-track'),slides=[...track.children],prev=carousel.querySelector('.reel-prev'),next=carousel.querySelector('.reel-next'),count=carousel.querySelector('.reel-counter strong'),progress=carousel.querySelector('.reel-progress span'),status=carousel.querySelector('.reel-status');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let active=0,down=false,startX=0,startScroll=0,moved=false;const step=()=>slides[0].getBoundingClientRect().width+parseFloat(getComputedStyle(track).gap);function update(){const max=track.scrollWidth-track.clientWidth;active=Math.min(slides.length-1,Math.round(track.scrollLeft/step()));count.textContent=String(active+1).padStart(2,'0');progress.style.width=`${max>0?Math.max(8,track.scrollLeft/max*100):100}%`;prev.disabled=track.scrollLeft<4;next.disabled=track.scrollLeft>=max-4}function move(direction){track.dispatchEvent(new CustomEvent('reelchange',{detail:{video:slides[Math.max(0,Math.min(slides.length-1,Math.round(track.scrollLeft/step())+direction))].querySelector('video')}}));track.scrollBy({left:direction*step(),behavior:reduced?'instant':'smooth'});status.textContent=document.documentElement.lang==='en'?'Moving through the reels':'Explorando los reels'}prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));track.addEventListener('scroll',update,{passive:true});addEventListener('resize',update);track.addEventListener('keydown',e=>{if(e.target!==track)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}else if(e.key==='Home'||e.key==='End'){e.preventDefault();track.scrollTo({left:e.key==='Home'?0:track.scrollWidth,behavior:reduced?'instant':'smooth'})}});track.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||e.target.closest('a,button:not(.film-pause)'))return;down=true;moved=false;startX=e.clientX;startScroll=track.scrollLeft;});track.addEventListener('pointermove',e=>{if(!down)return;const dx=e.clientX-startX;if(Math.abs(dx)>6&&!moved){moved=true;track.classList.add('dragging');track.setPointerCapture(e.pointerId)}if(moved){e.preventDefault();track.scrollLeft=startScroll-dx}});function end(e){if(!down)return;down=false;track.classList.remove('dragging');if(track.hasPointerCapture(e.pointerId))track.releasePointerCapture(e.pointerId);if(moved)track.scrollTo({left:Math.round(track.scrollLeft/step())*step(),behavior:reduced?'instant':'smooth'})}track.addEventListener('pointerup',end);track.addEventListener('pointercancel',end);track.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopImmediatePropagation();moved=false}},true);track.addEventListener('dragstart',e=>e.preventDefault());const sizeObserver=new ResizeObserver(()=>requestAnimationFrame(update));sizeObserver.observe(track);slides.forEach(slide=>sizeObserver.observe(slide));addEventListener('load',update);document.fonts?.ready.then(update);requestAnimationFrame(update);update();})();
